import { request } from '../utils/request';

export function fetchConversations() {
	return request({
		url: '/api/conversations'
	});
}

export function fetchConversationUnreadCount() {
	return request({
		url: '/api/conversations/unread-count'
	});
}

export function fetchPrivateMessageSubscriptionStatus() {
	return request({
		url: '/api/message-subscriptions/private/status'
	});
}

export function recordPrivateMessageSubscriptionGrant(templateId) {
	return request({
		url: '/api/message-subscriptions/private/grant',
		method: 'POST',
		data: { templateId }
	});
}

export function ensurePrivateConversation(peerUserId) {
	return request({
		url: '/api/conversations/private',
		method: 'POST',
		data: { peerUserId }
	});
}

export function fetchConversationMessages(id, params = {}) {
	return request({
		url: `/api/conversations/${id}/messages`,
		data: params
	});
}

export function sendConversationMessage(id, payload) {
	return request({
		url: `/api/conversations/${id}/messages`,
		method: 'POST',
		data: payload
	});
}

export function markConversationRead(id) {
	return request({
		url: `/api/conversations/${id}/read`,
		method: 'POST'
	});
}

export function openFlashImage(conversationId, messageId) {
	return request({
		url: `/api/conversations/${conversationId}/messages/${messageId}/flash/open`,
		method: 'POST'
	});
}

export function closeFlashImage(conversationId, messageId) {
	return request({
		url: `/api/conversations/${conversationId}/messages/${messageId}/flash/close`,
		method: 'POST'
	});
}

export function deleteConversation(id) {
	return request({
		url: `/api/conversations/${id}`,
		method: 'DELETE'
	});
}

export function markMessageDelivered(conversationId, messageId) {
	return request({
		url: `/api/conversations/${conversationId}/messages/${messageId}/delivered`,
		method: 'POST'
	});
}
